window.__finlexDocLoaded(88,{"id":88,"articles":[{"id":2808,"no":"案例一","heading":"湖南省湘西土家族苗族自治州税务部门联合公安机关依法查处湖南宸睿通信科技有限公司及其实际控制人彭宇勾结税务人员骗取出口退税","text":"湖南省湘西土家族苗族自治州税务部门联合公安机关依法查处湖南宸睿通信科技有限公司及其实际控制人彭宇勾结税务人员骗取出口退税案件。经查，2020年至2021年，湖南宸睿通信科技有限公司及其实际控制人彭宇勾结湘西高新区税务局工作人员向峰，通过签订虚假买卖合同、虚开增值税专用发票、接受上游企业虚开增值税专用发票等手段骗取出口退税339.28万元。2025年9月，税务部门依据《中华人民共和国税收征收管理法》等相关法律法规规定，对其作出追缴出口退税款、停止为其办理出口退税两年三个月的处理处罚决定。目前，案件由公安机关进一步侦办。2025年10月，湘西高新区税务局工作人员向峰被给予开除党籍、开除公职处分；2025年12月，向峰因犯受贿罪、徇私舞弊发售发票、出口退税罪等，被泸溪县人民法院依法判处有期徒刑六年六个月，并追缴违法所得。","seq":0},{"id":2809,"no":"案例二","heading":"国家税务总局临沂市税务局第一稽查局依法查处临沂群策国际贸易有限公司虚假填报商品品目骗取出口退税案件","text":"国家税务总局临沂市税务局第一稽查局依法查处临沂群策国际贸易有限公司虚假填报商品品目骗取出口退税案件。经查，2022年至2024年，临沂群策国际贸易有限公司在办理出口货物报关及退税申报环节，通过虚假填报出口商品品目，将本不予退税的商品，违规申报为适用13%退税率的商品等手段骗取出口退税811.75万元。2026年3月，税务部门依据《中华人民共和国税收征收管理法》等相关法律法规规定，对其作出追缴出口退税款并处两倍罚款、停止为其办理出口退税两年的处理处罚决定。目前，涉案税款已全部追缴入库，罚款正在依法追缴，该案已依法移送公安机关进一步侦办。","seq":1,"links":[{"doc_id":76,"tier":"L5","score":36,"rel_kind":"applies_to","target_seq":0,"target_art_no":"第一条","dir":"out","note":"实务案例涉及《中华人民共和国税收征收管理法》"}]},{"id":2810,"no":"案例三","heading":"国家税务总局鹤壁市税务局稽查局联合公安部门依法查处河南艾麦尼调味食品有限公司骗取出口退税案件","text":"国家税务总局鹤壁市税务局稽查局联合公安部门依法查处河南艾麦尼调味食品有限公司骗取出口退税案件。经查，2020年至2024年，河南艾麦尼调味食品有限公司通过虚开农产品收购发票、虚开增值税专用发票、虚假结汇等手段骗取出口退税1230.95万元。2025年5月，税务部门依据《中华人民共和国税收征收管理法》等相关法律法规规定，对其作出追缴出口退税款、停止为其办理出口退税三年的处理处罚决定。2026年7月，河南省鹤壁市中级人民法院对该案作出判决，该公司实际控制人张庆因犯骗取出口退税罪，被判处有期徒刑十三年并处罚金。","seq":2,"links":[{"doc_id":76,"tier":"L5","score":36,"rel_kind":"applies_to","target_seq":0,"target_art_no":"第一条","dir":"out","note":"实务案例涉及《中华人民共和国税收征收管理法》"}]},{"id":2811,"no":"案例四","heading":"国家税务总局孝感市税务局第一稽查局依法查处湖北睿澳电子科技有限公司骗取出口退税案件，4名税务人员因在出口退税管理中存在执","text":"国家税务总局孝感市税务局第一稽查局依法查处湖北睿澳电子科技有限公司骗取出口退税案件，4名税务人员因在出口退税管理中存在执法过错被追究责任。经查，2020年至2023年，湖北睿澳电子科技有限公司通过虚开增值税专用发票、签订虚假购销合同等手段骗取出口退税169.65万元。2024年10月，税务部门依据《中华人民共和国税收征收管理法》等相关法律法规规定，对其作出追缴出口退税款并处一倍罚款、停止为其办理出口退税一年半的处理处罚决定。目前，该案件已移送检察机关审查起诉。按照“一案双查”工作要求，税务部门对在该案出口退税管理中存在执法过错的税务人员进行责任追究，2026年4月，大悟县税务局1名税务人员被给予党内严重警告处分，2025年11月，大悟县税务局3名税务人员被追究税务执法过错责任。","seq":3,"links":[{"doc_id":76,"tier":"L5","score":36,"rel_kind":"applies_to","target_seq":0,"target_art_no":"第一条","dir":"out","note":"实务案例涉及《中华人民共和国税收征收管理法》"}]},{"id":2812,"no":"案例五","heading":"国家税务总局深圳市税务局第三稽查局依法查处以陈华为实际控制人的3户企业骗取出口退税案件","text":"国家税务总局深圳市税务局第三稽查局依法查处以陈华为实际控制人的3户企业骗取出口退税案件。经查，2020年至2024年，以陈华为实际控制人的深圳市金丝雨贸易有限公司等3户企业，在无真实货物交易的情况下，通过虚假出口报关、虚假结汇、接受上游企业虚开增值税专用发票等手段骗取出口退税2276.97万元。2024年12月，税务部门依据《中华人民共和国税收征收管理法》等相关法律法规规定，对其作出追缴出口退税款并处一倍罚款、停止为其办理出口退税三年的处理处罚决定。目前，陈华等6人已由检察机关向人民法院提起公诉。 通过虚开发票、签订虚假买卖合同、虚假填报商品品目等手段骗取出口退税，属于税收征管法明确的违法行为。合规经营是外贸行业长期健康发展的基石，出口企业应自觉如实申报纳税，依法依规办理出口退税。税务部门将在不断优化税费服务的同时，持续依法查处各类涉税违法行为，严厉打击骗取出口退税等恶意偷骗税行为，切实维护法治公平税收营商环境。","seq":4}]});
